CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE SCHEMA auth;
CREATE SCHEMA private;
CREATE TABLE public.fleets (id uuid PRIMARY KEY);
CREATE TABLE public.fleet_members (
  fleet_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL,
  PRIMARY KEY (fleet_id, user_id)
);
ALTER TABLE public.fleet_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.drivers (
  id uuid PRIMARY KEY, fleet_id uuid NOT NULL, status text NOT NULL, user_id uuid,
  full_name text NOT NULL DEFAULT 'Test Driver', license_expires_at date
);
CREATE TABLE public.vehicles (
  id uuid PRIMARY KEY, fleet_id uuid NOT NULL, registration_number text,
  status text NOT NULL, assigned_driver_id uuid, updated_at timestamptz DEFAULT now(),
  test_due_at date DEFAULT (current_date + 365), insurance_due_at date DEFAULT (current_date + 365), registration_due_at date DEFAULT (current_date + 365)
);
CREATE TABLE public.tasks (
  id uuid PRIMARY KEY, fleet_id uuid NOT NULL, assigned_driver_id uuid NOT NULL,
  assigned_vehicle_id uuid NOT NULL, status text NOT NULL, updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.trips (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id uuid NOT NULL,
  task_id uuid, driver_id uuid NOT NULL, vehicle_id uuid NOT NULL,
  status text NOT NULL, origin_address text, destination_address text,
  started_at timestamptz, ended_at timestamptz, updated_at timestamptz DEFAULT now()
);
CREATE TABLE public.trip_locations (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  trip_id uuid NOT NULL,
  driver_id uuid NOT NULL,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL,
  speed_kmh numeric,
  heading_degrees numeric,
  recorded_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.inspections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id uuid NOT NULL,
  trip_id uuid, vehicle_id uuid NOT NULL, driver_id uuid NOT NULL,
  inspection_type text NOT NULL, checklist jsonb NOT NULL, defects text,
  passed boolean NOT NULL, inspected_at timestamptz NOT NULL
);
CREATE TABLE public.maintenance_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fleet_id uuid NOT NULL,
  vehicle_id uuid,
  maintenance_type text,
  description text,
  scheduled_at date,
  completed_at date,
  cost numeric,
  odometer_km numeric,
  status text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  incident_id uuid
);
CREATE TABLE public.incidents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), fleet_id uuid NOT NULL,
  driver_id uuid NOT NULL, vehicle_id uuid NOT NULL, severity text NOT NULL,
  incident_type text NOT NULL, description text NOT NULL, status text NOT NULL,
  reported_at timestamptz NOT NULL, created_by uuid NOT NULL,
  resolved_at timestamptz
);
ALTER TABLE public.inspections ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
CREATE FUNCTION private.has_fleet_role(target_fleet uuid, allowed_roles text[])
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.fleet_members fm
    WHERE fm.fleet_id = target_fleet
      AND fm.user_id = auth.uid()
      AND fm.role = ANY(allowed_roles)
  )
$$;
CREATE FUNCTION private.is_fleet_member(target_fleet uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.fleet_members fm
    WHERE fm.fleet_id = target_fleet AND fm.user_id = auth.uid()
  )
$$;

ALTER TABLE public.trips ENABLE ROW LEVEL SECURITY;
CREATE POLICY trips_select_member
ON public.trips
FOR SELECT
TO authenticated
USING (private.is_fleet_member(fleet_id));

ALTER TABLE public.drivers ENABLE ROW LEVEL SECURITY;
CREATE POLICY drivers_select_member
ON public.drivers
FOR SELECT
TO authenticated
USING (private.is_fleet_member(fleet_id));
CREATE POLICY drivers_insert_managers
ON public.drivers
FOR INSERT
TO authenticated
WITH CHECK (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']));
CREATE POLICY drivers_update_managers
ON public.drivers
FOR UPDATE
TO authenticated
USING (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']))
WITH CHECK (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']));
CREATE POLICY drivers_delete_managers
ON public.drivers
FOR DELETE
TO authenticated
USING (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']));

ALTER TABLE public.trip_locations ENABLE ROW LEVEL SECURITY;
CREATE POLICY trip_locations_select_member
ON public.trip_locations
FOR SELECT
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.trips t
    WHERE t.id = trip_locations.trip_id
      AND private.is_fleet_member(t.fleet_id)
  )
);
CREATE POLICY trip_locations_insert_authorized
ON public.trip_locations
FOR INSERT
TO authenticated
WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.trips t
    WHERE t.id = trip_locations.trip_id
      AND t.status = 'active'
      AND t.driver_id = trip_locations.driver_id
      AND (
        private.has_fleet_role(t.fleet_id, ARRAY['owner','fleet_manager','dispatcher'])
        OR EXISTS (
          SELECT 1 FROM public.drivers d
          WHERE d.id = t.driver_id
            AND d.fleet_id = t.fleet_id
            AND d.user_id = (SELECT auth.uid())
            AND d.status = 'active'
        )
      )
  )
);

ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
CREATE POLICY vehicles_select_member
ON public.vehicles
FOR SELECT
TO authenticated
USING (private.is_fleet_member(fleet_id));
CREATE POLICY vehicles_insert_managers
ON public.vehicles
FOR INSERT
TO authenticated
WITH CHECK (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']));
CREATE POLICY vehicles_update_authorized
ON public.vehicles
FOR UPDATE
TO authenticated
USING (
  private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher'])
  OR EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE d.id = vehicles.assigned_driver_id
      AND d.fleet_id = vehicles.fleet_id
      AND d.user_id = (SELECT auth.uid())
  )
)
WITH CHECK (
  private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher'])
  OR (
    status IN ('on_trip','available','assigned')
    AND EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id = vehicles.assigned_driver_id
        AND d.fleet_id = vehicles.fleet_id
        AND d.user_id = (SELECT auth.uid())
    )
  )
);
CREATE POLICY vehicles_delete_managers
ON public.vehicles
FOR DELETE
TO authenticated
USING (private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher']));

ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_select_member
ON public.tasks
FOR SELECT
TO authenticated
USING (private.is_fleet_member(fleet_id));
CREATE POLICY tasks_update_authorized
ON public.tasks
FOR UPDATE
TO authenticated
USING (
  private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher'])
  OR EXISTS (
    SELECT 1 FROM public.drivers d
    WHERE d.id = tasks.assigned_driver_id
      AND d.fleet_id = tasks.fleet_id
      AND d.user_id = (SELECT auth.uid())
  )
)
WITH CHECK (
  private.has_fleet_role(fleet_id, ARRAY['owner','fleet_manager','dispatcher'])
  OR (
    status IN ('in_progress','completed')
    AND EXISTS (
      SELECT 1 FROM public.drivers d
      WHERE d.id = tasks.assigned_driver_id
        AND d.fleet_id = tasks.fleet_id
        AND d.user_id = (SELECT auth.uid())
    )
  )
);

ALTER TABLE public.maintenance_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY maintenance_select_member
ON public.maintenance_records
FOR SELECT
TO authenticated
USING (private.is_fleet_member(fleet_id));

ALTER TABLE public.incidents ENABLE ROW LEVEL SECURITY;
CREATE POLICY incidents_insert_member
ON public.incidents
FOR INSERT
TO authenticated
WITH CHECK (private.is_fleet_member(fleet_id));


-- Simulate Supabase's normal authenticated table grants before the migration
-- so the migration's explicit revocations are exercised by the tests.
GRANT SELECT, INSERT, UPDATE, DELETE ON public.trips, public.trip_locations, public.inspections,
  public.tasks, public.vehicles, public.drivers, public.incidents, public.fleet_members, public.maintenance_records,
  public.fleets TO authenticated;
